  ],
  "contradictory_card_ids": ["C22"],
  "prediction_basis_card_ids": [
    "C01", "C11", "C29", "C06", "C30", "C02", "C10", "C16", "C18", "C33",
    "C12", "C23", "C26", "C03", "C24", "C27", "C17"
  ],
  "claims": [
    {
      "claim": "Benazepril, an ethyl-ester prodrug with a basic amine, has measured human oral bioavailability of 28–37% and >37%, and ≈30% in a summary, directly supporting F ≥20% for the query's ester-prodrug class.",
      "card_ids": ["C01", "C11", "C29"]
    },
    {
      "claim": "Delapril, another ester prodrug ACE inhibitor, has absolute oral bioavailability >55% in humans, showing that ester prodrugs with similar lipophilicity can exceed the threshold.",
      "card_ids": ["C06", "C30"]
    },
    {
      "claim": "Solifenacin, a basic tertiary amine with low TPSA and no H-bond donors, has absolute oral bioavailability of 88% (approximately 90%), supporting favorable absorption for the query's physicochemical profile.",
      "card_ids": ["C02", "C10", "C16", "C18", "C20", "C33"]
    },
    {
      "claim": "Setipiprant, a lipophilic small molecule, has human bioavailability at least 50% and preclinical F of 32–55% in rats and 55% in dogs; L3 oral exposure records show substantial Cmax/AUC after 500 mg, consistent with good oral exposure.",
      "card_ids": ["C12", "C23", "C26", "C43", "C44", "C45"]
    },
    {
      "claim": "Compound 12, a lipophilic molecule with a basic amine, has predicted human F of 58% and preclinical F of 72% in mice and 35% in rats, supporting F ≥20%.",
      "card_ids": ["C03", "C24", "C27"]
    },
    {
      "claim": "Neotame, a fasted oral small molecule, had at least 34.3% systemic availability, supporting F ≥20%.",
      "card_ids": ["C17"]
    },
    {
      "claim": "The only low-F record, benazepril in cats (5.3%), is species-specific and does not transfer to human oral bioavailability; it does not overturn the human high-F evidence.",
      "card_ids": ["C22"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C43", "C44", "C45"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41", "C42"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; no IV comparator data are supplied.",
    "First-pass ester hydrolysis and CYP-mediated bioactivation of the thienopyridine prodrug are not directly quantified in the supplied records.",
    "Experimental solubility and permeability data for the query are absent; only physicochemical estimates are available.",
    "Most transferred records come from different therapeutic classes, species, or disease conditions (e.g., cirrhosis), limiting direct extrapolation.",
    "The only low-F record is from cats and may not reflect human bioavailability.",
    "The L3 sufentanil oral Cmax record (C39) shows much lower oral than IV Cmax, but lacks IV dose and AUC, so it cannot be used to infer F <20%."
  ],
  "decision_summary": "Prediction is high: all transferable L1/L2 records report F ≥20%, with the most relevant ester-prodrug contexts (benazepril 28–37%/>37%/≈30%, delapril >55%) and high-F basic-amine contexts (solifenacin 88%/≈90%) supporting F ≥20% for the query. L3 oral exposure records for setipiprant are consistent with good oral exposure, while the sufentanil Cmax record is not dose-normalized and does not provide affirmative evidence for F <20%. Residual uncertainty about first-pass ester hydrolysis is captured as moderate confidence."
}

